task_text:
Fix this Python function.

def add(a, b)
    return a + b

Refactor this JavaScript loop to use `map` instead of a `for` loop.

let result = [];
for (let i = 0; i < arr.length; i++) {
  result.push(arr[i] * 2);
}

Review this code for bugs.

def divide(a, b):
    return a / b

Fix this JavaScript function that should return the sum of an array but returns NaN.

function sum(arr) {
  let total;
  arr.forEach(n => total += n);
  return total;
}

Fix the off-by-one error in this loop that's supposed to print numbers 1 to 5.

for i in range(5):
    print(i)

Convert this callback-based Node.js function to use async/await.

function getData(cb) {
  fs.readFile('file.txt', (err, data) => {
    if (err) return cb(err);
    cb(null, data);
  });
}

Fix this Python code that raises `KeyError` when a key doesn't exist.

config = {'debug': True}
print(config['verbose'])

Fix this JavaScript function that mutates the original array unintentionally.

function sortDescending(arr) {
  return arr.sort((a, b) => b - a);
}

Refactor this nested if-else chain into a cleaner structure.

if score >= 90:
    grade = 'A'
else:
    if score >= 80:
        grade = 'B'
    else:
        if score >= 70:
            grade = 'C'
        else:
            grade = 'F'

Debug this React component that doesn't re-render when state changes.

const [count, setCount] = useState(0);
function increment() {
  count = count + 1;
}

Fix this bug where a Python function compares floats and fails due to precision issues.

if 0.1 + 0.2 == 0.3:
    print('equal')

Review and improve this Python code for readability and PEP 8 compliance.

def calc(x,y,z):
    if x==1:
        return y+z
    else:
        return y-z
